"""Private records may use the explicitly ignored artifacts root after relocation."""

import subprocess
from pathlib import Path


def validate_private_path(path, *, error_type=ValueError):
    path = Path(path).resolve()
    package_root = Path(__file__).resolve().parents[2]
    # A nested checkout owns its paths. An enclosing checkout does not make
    # this checkout's ignored artifacts relative to the enclosing root.
    repository = next((p for p in (path, *path.parents) if (p / ".git").exists()), None)
    if repository is None and (package_root / "pyproject.toml").exists() and path.is_relative_to(package_root):
        repository = package_root
    if repository is None:
        return
    private = repository / "artifacts"
    # Resolve first: symlinks cannot escape into public source or another repo.
    if not path.is_relative_to(private) or private.resolve() != private:
        raise error_type("private state must be outside version-controlled directories or in verified ignored artifacts")
    try:
        ignored = subprocess.run(["git", "-C", str(repository), "check-ignore", "-q", "--", str(path)],
                                 capture_output=True, timeout=10, check=False)
        tracked = subprocess.run(["git", "-C", str(repository), "ls-files", "-z", "--", "artifacts"],
                                 capture_output=True, timeout=10, check=False)
    except (OSError, subprocess.SubprocessError) as error:
        raise error_type("private artifacts exclusion could not be verified") from error
    if ignored.returncode != 0 or tracked.returncode != 0 or tracked.stdout:
        raise error_type("private artifacts must be git ignored and contain no tracked files")
